PROGRAM motor_interlock
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Motor : BOOL;
END_VAR
VAR
    MotorLatch : BOOL := FALSE;
    EmergencyStopTimer : TON;
END_VAR

MotorLatch := FALSE;

IF NOT EStop THEN
    MotorLatch := FALSE;
    Motor := FALSE;
    EmergencyStopTimer(IN := TRUE, PT := T#0s);
ELSE
    IF Start AND NOT Stop THEN
        MotorLatch := TRUE;
    ELSIF Stop THEN
        MotorLatch := FALSE;
    END_IF;
    Motor := MotorLatch AND NOT EStop;
END_IF;

END_PROGRAM

