    MotorLatch := FALSE;
END_IF;

Motor := MotorLatch AND NOT EStop;
END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    PumpInTimer : TON;
    ValveOutTimer : TON;
    LowLimit : CONST INT := 10;
    HighLimit : CONST INT := 90;
END_VAR

IF Level <= LowLimit THEN
    PumpIn := TRUE;
    PumpInTimer(IN := TRUE, PT := T#0s);
ELSEIF Level >= HighLimit THEN
    PumpIn := FALSE;
    PumpInTimer(IN := FALSE, PT := T#0s);
    ValveOut := TRUE;
    ValveOutTimer(IN := TRUE, PT := T#0s);
ELSE
    PumpIn := FALSE;
    PumpInTimer(IN := FALSE, PT := T#0s);
    ValveOut := FALSE;
    ValveOutTimer(IN := FALSE, PT := T#0s);
END_IF;

IF PumpInTimer.Q AND Level >= HighLimit THEN
    PumpIn := FALSE;
END_IF;
END_PROGRAM

PROGRAM tank_level
VAR_INPUT
