END_VAR
VAR
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    PumpTimer : TON;
END_VAR

// Check if level is below low limit or above high limit
IF Level <= LowLimit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSIF Level >= HighLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

// Ensure PumpIn does not run when Level is at or above HighLimit
IF Level >= HighLimit AND PumpIn THEN
    PumpIn := FALSE;
END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    PumpInTimer : TON;
    ValveOutTimer : TON;
    LowLimit : CONST INT := 10;
    HighLimit : CONST INT := 90;
END_VAR

// Check if the level is at or above the high limit
IF Level >= HighLimit THEN
    // Ensure the pump is not running
    PumpIn := FALSE;

    // Open the outlet valve if not already open
    IF NOT ValveOut THEN
        ValveOut := TRUE;
        ValveOutTimer(IN := TRUE, PT := T#0s);
    END_IF;
ELSE
    // Close the outlet valve if above the low limit
    IF Level > LowLimit AND ValveOut THEN
        ValveOut := FALSE;
        ValveOutTimer(IN := FALSE, PT := T#0s);
    END_IF;

    // Turn on the pump if below the low limit
    IF Level <= LowLimit THEN
        PumpIn := TRUE;
        PumpInTimer(IN := TRUE, PT := T#0s);
    ELSE
        // Turn off the pump if above the low limit
        PumpIn := FALSE;
        PumpInTimer(IN := FALSE, PT := T#0s);
    END_IF;
END_IF;

// Reset the timers if conditions change
IF Level <> LastLevel THEN
    PumpInTimer(IN := FALSE, PT := T#0s);
    ValveOutTimer(IN := FALSE, PT := T#0s);
END_IF;

// Store the current level for comparison in the next cycle
LastLevel := Level;
END_PROGRAM

