PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    PumpTimer : TON;
END_VAR

// Check if level is within safe limits
IF Level >= LowLimit AND Level <= HighLimit THEN
    // Determine pump state based on hysteresis
    IF Level <= LowLimit THEN
        PumpIn := TRUE;
        PumpTimer(IN := FALSE, PT := T#0s);
    ELSIF Level >= HighLimit THEN
        PumpIn := FALSE;
        PumpTimer(IN := FALSE, PT := T#0s);
        ValveOut := TRUE;
    ELSE
        PumpIn := FALSE;
        PumpTimer(IN := FALSE, PT := T#0s);
        ValveOut := FALSE;
    END_IF;
ELSE
    // Safety condition: pump must not run if level is at or above high limit
    PumpIn := FALSE;
    PumpTimer(IN := FALSE, PT := T#0s);
    ValveOut := FALSE;
END_IF;

// Reset ValveOut if level drops below low limit
IF Level <= LowLimit THEN
    ValveOut := FALSE;
END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    PumpInTimer : TON;
    ValveOutTimer : TON;
    LowLimit : CONST INT := 10;
    HighLimit : CONST INT := 90;
END_VAR

// Initialize timers
PumpInTimer(IN := FALSE, PT := T#0s);
ValveOutTimer(IN := FALSE, PT := T#0s);

CASE Level OF
    // Turn off pump and open valve if level is at or above high limit
    HighLimit..100:
        PumpIn := FALSE;
        ValveOut := TRUE;

    // Turn on pump if level is at or below low limit
    0..LowLimit:
        PumpIn := TRUE;
        ValveOut := FALSE;

    // Maintain pump state and close valve otherwise
    LowLimit..HighLimit:
        PumpIn := NOT PumpIn;
        ValveOut := FALSE;
END_CASE

// Safety check: Ensure pump is not running when level is at or above high limit
IF Level >= HighLimit THEN
    PumpIn := FALSE;
END_IF

END_PROGRAM

