PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    DoorA_Open : BOOL := FALSE;
    DoorB_Open : BOOL := FALSE;
    T_A : TON;
    T_B : TON;
END_VAR

// Reset timers when doors are not open
T_A(IN := NOT DoorA_Open, PT := T#0s);
T_B(IN := NOT DoorB_Open, PT := T#0s);

// Logic for opening Door A
IF OpenA_Cmd AND NOT DoorB_Open THEN
    DoorA := TRUE;
    DoorB := FALSE;
    T_A(IN := TRUE, PT := T#1s); // Hold open for 1 second
ELSE
    DoorA := FALSE;
END_IF;

// Logic for opening Door B
IF OpenB_Cmd AND NOT DoorA_Open THEN
    DoorB := TRUE;
    DoorA := FALSE;
    T_B(IN := TRUE, PT := T#1s); // Hold open for 1 second
ELSE
    DoorB := FALSE;
END_IF;

// Ensure only one door can be open at a time
IF T_A.Q AND T_B.Q THEN
    DoorA := FALSE;
    DoorB := FALSE;
END_IF;

END_PROGRAM

