PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR
VAR
    DoorA_Open : BOOL := FALSE;
    DoorB_Open : BOOL := FALSE;
    T_A_to_B : TON;
    T_B_to_A : TON;
END_VAR

// Check if door A should be opened
IF OpenA_Cmd AND NOT OpenB_Cmd AND NOT DoorA_Open THEN
    DoorA := TRUE;
    DoorB := FALSE;
    T_A_to_B(IN := TRUE, PT := T#0s);
    T_B_to_A(IN := FALSE, PT := T#0s);
ELSIF OpenA_Cmd AND OpenB_Cmd THEN
    // Door A has priority
    DoorA := TRUE;
    DoorB := FALSE;
    T_A_to_B(IN := TRUE, PT := T#0s);
    T_B_to_A(IN := FALSE, PT := T#0s);
ELSE
    DoorA := FALSE;
    DoorB := FALSE;
    T_A_to_B(IN := FALSE, PT := T#0s);
    T_B_to_A(IN := FALSE, PT := T#0s);
END_IF;

// Check if door B should be opened
IF OpenB_Cmd AND NOT OpenA_Cmd AND NOT DoorB_Open THEN
    DoorB := TRUE;
    DoorA := FALSE;
    T_B_to_A(IN := TRUE, PT := T#0s);
    T_A_to_B(IN := FALSE, PT := T#0s);
ELSEIF OpenA_Cmd AND OpenB_Cmd THEN
    // Door A has priority
    DoorA := TRUE;
    DoorB := FALSE;
    T_A_to_B(IN := TRUE, PT := T#0s);
    T_B_to_A(IN := FALSE, PT := T#0s);
ELSE
    DoorA := FALSE;
    DoorB := FALSE;
    T_A_to_B(IN := FALSE, PT := T#0s);
    T_B_to_A(IN := FALSE, PT := T#0s);
END_IF;

END_PROGRAM

PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR
VAR
    T_A : TON;
    T_B : TON;
    A_opened : BOOL;
    B_opened : BOOL;
END_VAR

DoorA := FALSE;
DoorB := FALSE;

CASE 
    WHEN OpenA_Cmd AND NOT OpenB_Cmd THEN
        IF NOT A_opened THEN
            T_A(IN := TRUE, PT := T#0s);
            A_opened := TRUE;
        END_IF;
        IF T_A.Q THEN
            DoorA := TRUE;
        ELSE
            DoorA := FALSE;
        END_IF;
        DoorB := FALSE;
    ELSIF OpenB_Cmd AND NOT OpenA_Cmd THEN
        IF NOT B_opened THEN
            T_B(IN := TRUE, PT := T#0s);
            B_opened := TRUE;
        END_IF;
        IF T_B.Q THEN
            DoorB := TRUE;
        ELSE
            DoorB := FALSE;
        END_IF;
        DoorA := FALSE;
    ELSE
        DoorA := FALSE;
        DoorB := FALSE;
        A_opened := FALSE;
        B_opened := FALSE;
END_CASE;

