PROGRAM intersection
VAR
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    State : INT := 0;
    TNSGreen, TEWGreen, TAllRed : TON;
    PT_GREEN : TIME := T#2s;
    PT_YELLOW : TIME := T#1s;
    PT_ALLRED : TIME := T#1s;
END_VAR

// Initialize timers
TNSGreen(IN := FALSE, PT := PT_GREEN);
TEWGreen(IN := FALSE, PT := PT_GREEN);
TAllRed(IN := FALSE, PT := PT_ALLRED);

// Main loop
WHILE TRUE DO
    // Update state based on current timer status
    CASE State OF
        0:
            NS_G := TRUE;
            NS_Y := FALSE;
            NS_R := FALSE;
            EW_G := FALSE;
            EW_Y := FALSE;
            EW_R := TRUE;
            TNSGreen(IN := TRUE);
            TEWGreen(IN := FALSE);
            TAllRed(IN := FALSE);
            IF TNSGreen.Q THEN
                State := 1;
            END_IF;

        1:
            NS_G := FALSE;
            NS_Y := TRUE;
            NS_R := FALSE;
            EW_G := FALSE;
            EW_Y := FALSE;
            EW_R := TRUE;
            TNSGreen(IN := FALSE);
            TEWGreen(IN := FALSE);
            TAllRed(IN := FALSE);
            IF TNSGreen.Q THEN
                State := 2;
            END_IF;

        2:
            NS_G := FALSE;
            NS_Y := FALSE;
            NS_R := TRUE;
            EW_G := FALSE;
            EW_Y := FALSE;
            EW_R := TRUE;
            TNSGreen(IN := FALSE);
            TEWGreen(IN := FALSE);
            TAllRed(IN := TRUE);
            IF TAllRed.Q THEN
                State := 3;
            END_IF;

        3:
            NS_G := FALSE;
            NS_Y := FALSE;
            NS_R := TRUE;
            EW_G := TRUE;
            EW_Y := FALSE;
            EW_R := FALSE;
            TNSGreen(IN := FALSE);
            TEWGreen(IN := TRUE);
            TAllRed(IN := FALSE);
            IF TEWGreen.Q THEN
                State := 4;
            END_IF;

        4:
            NS_G := FALSE;
            NS_Y := FALSE;
            NS_R := TRUE;
            EW_G := FALSE;
            EW_Y := TRUE;
            EW_R := FALSE;
            TNSGreen(IN := FALSE);
            TEWGreen(IN := FALSE);
            TAllRed(IN := FALSE);
            IF TEWGreen.Q THEN
                State := 5;
            END_IF;

        5:
            NS_G := FALSE;
            NS_Y := FALSE;
            NS_R := TRUE;
            EW_G := FALSE;
            EW_Y := FALSE;
            EW_R := TRUE;
            TNSGreen(IN := FALSE);
            TEWGreen(IN := FALSE);
            TAllRed(IN := TRUE);
            IF TAllRed.Q THEN
                State := 0;
            END_IF;
    END_CASE;
END_WHILE
END_PROGRAM

PROGRAM intersection
VAR
    State : INT;
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    TON_NS_green, TON_NS_yellow, TON_NS_allred : TON;
    TON_EW_green, TON_EW_yellow, TON_EW_allred : TON;
END_VAR

// Initialize timers
TON_NS_green(IN := FALSE, PT := T#0s);
TON_NS_yellow(IN := FALSE, PT := T#0s);
TON_NS_allred(IN := FALSE, PT := T#0s);
TON_EW_green(IN := FALSE, PT := T#0s);
TON_EW_yellow(IN := FALSE, PT := T#0s);
TON_EW_allred(IN := FALSE, PT := T#0s);

// Main loop
WHILE TRUE DO
    CASE State OF
        0:
            // NS green, EW red
            NS_G := TRUE;
            NS_Y := FALSE;
            NS_R := FALSE;
            EW_G := FALSE;
            EW_Y := FALSE;
            EW_R := TRUE;

            TON_NS_green(IN := TRUE, PT := T#2s);
            TON_EW_red(IN := TRUE, PT := T#2s);

            IF TON_NS_green.Q THEN
                State := 1;
            END_IF;

        1:
            // NS yellow, EW red
            NS_G := FALSE;
            NS_Y := TRUE;
            NS_R := FALSE;
            EW_G := FALSE;
            EW_Y := FALSE;
            EW_R := TRUE;

            TON_NS_yellow(IN := TRUE, PT := T#1s);
            TON_EW_red(IN := TRUE, PT := T#1s);

            IF TON_NS_yellow.Q THEN
                State := 2;
            END_IF;

        2:
            // All red clearance
            NS_G := FALSE;
            NS_Y := FALSE;
            NS_R := TRUE;
            EW_G := FALSE;
            EW_Y := FALSE;
            EW_R := TRUE;

            TON_NS_allred(IN := TRUE, PT := T#1s);
            TON_EW_allred(IN := TRUE, PT := T#1s);

            IF TON_NS_allred.Q AND TON_EW_allred.Q THEN
                State := 3;
            END_IF;

        3:
            // EW green, NS red
            NS_G := FALSE;
            NS_Y := FALSE;
            NS_R := TRUE;
            EW_G := TRUE;
            EW_Y := FALSE;
            EW_R := FALSE;

            TON_EW_green(IN := TRUE, PT := T#2s);
            TON_NS_red(IN := TRUE, PT := T#2s);

            IF TON_EW_green.Q THEN
                State := 4;
            END_IF;

        4:
            // EW yellow, NS red
            NS_G := FALSE;
            NS_Y := FALSE;
            NS_R := TRUE;
            EW_G := FALSE;
            EW_Y := TRUE;
            EW_R := FALSE;

