    5:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
END_CASE;

// Safety checks
IF NS_G AND EW_G THEN State := 0; END_IF;
IF NS_G AND EW_Y THEN State := 0; END_IF;
IF NS_Y AND EW_G THEN State := 0; END_IF;
IF NS_Y AND EW_Y THEN State := 0; END_IF;

// Update state after timers expire
IF TNS_green.Q THEN State := 1; END_IF;
IF TEW_green.Q THEN State := 3; END_IF;
