PROGRAM intersection
VAR
    State : INT;
    NS_G, NS_Y, NS_R : BOOL;
    EW_G, EW_Y, EW_R : BOOL;
    TNS_G, TEW_G : TON;
    TNS_Y, TEW_Y : TON;
    TNS_ALLRED, TEW_ALLRED : TON;
    PT_GREEN : TIME := T#2s;
    PT_YELLOW : TIME := T#1s;
    PT_ALLRED : TIME := T#1s;
END_VAR

// Initialize state and timers
State := 0;

// Main loop
WHILE TRUE DO
    // Reset all outputs
    NS_G := FALSE;
    NS_Y := FALSE;
    NS_R := FALSE;
    EW_G := FALSE;
    EW_Y := FALSE;
    EW_R := FALSE;

    CASE State OF
        0:
            // NS green, EW red
            NS_G := TRUE;
            TEW_ALLRED(IN := TRUE, PT := PT_ALLRED);
            TNS_ALLRED(IN := FALSE);

        1:
            // NS yellow, EW red
            NS_Y := TRUE;
            TEW_ALLRED(IN := TRUE, PT := PT_ALLRED);
            TNS_ALLRED(IN := FALSE);

        2:
            // All red
            NS_R := TRUE;
            EW_R := TRUE;
            TEW_ALLRED(IN := FALSE);
            TNS_ALLRED(IN := FALSE);

        3:
            // EW green, NS red
            EW_G := TRUE;
            TNS_ALLRED(IN := TRUE, PT := PT_ALLRED);
            TEW_ALLRED(IN := FALSE);

        4:
            // EW yellow, NS red
            EW_Y := TRUE;
            TNS_ALLRED(IN := TRUE, PT := PT_ALLRED);
            TEW_ALLRED(IN := FALSE);

        5:
            // All red
            NS_R := TRUE;
            EW_R := TRUE;
            TNS_ALLRED(IN := FALSE);
            TEW_ALLRED(IN := FALSE);
    END_CASE;

    // Check for safety condition: never both directions show a movement aspect simultaneously
    IF (NS_G OR NS_Y) AND (EW_G OR EW_Y) THEN
        // If unsafe, reset to initial state
        State := 0;
    END_IF;

    // Update state based on timers
    IF TNS_ALLRED.Q THEN
        State := (State + 1) MOD 6;
        TNS_ALLRED(IN := FALSE);
    END_IF;

    IF TEW_ALLRED.Q THEN
        State := (State + 1) MOD 6;
        TEW_ALLRED(IN := FALSE);
    END_IF;

    // Delay for one tick
    WAIT FOR 1ms;
END_WHILE

END_PROGRAM

PROGRAM elevator
VAR
    CallUp : BOOL;
    CallDown : BOOL;
    DoorClosed : BOOL;
    AtTop : BOOL;
    AtBottom : BOOL;
    MotorUp : BOOL;
    MotorDown : BOOL;
    State : INT := 0;
    UpTimer : TON;
    DownTimer : TON;
END_VAR

IF NOT DoorClosed THEN
    MotorUp := FALSE;
    MotorDown := FALSE;
ELSE
    CASE State OF
        0:  // At-bottom
            IF CallUp AND NOT AtTop THEN
                State := 1;
                MotorUp := TRUE;
                MotorDown := FALSE;
            ELSE
                MotorUp := FALSE;
                MotorDown := FALSE;
            END_IF;

        1:  // Moving-up
            MotorUp := TRUE;
            MotorDown := FALSE;
            IF AtTop OR (CallDown AND NOT AtBottom) THEN
                State := 2;
                MotorUp := FALSE;
                MotorDown := FALSE;
            END_IF;

        2:  // At-top
            IF CallDown AND NOT AtBottom THEN
                State := 3;
                MotorUp := FALSE;
                MotorDown := TRUE;
            ELSE
                MotorUp := FALSE;
                MotorDown := FALSE;
            END_IF;

        3:  // Moving-down
            MotorUp := FALSE;
            MotorDown := TRUE;
            IF AtBottom OR (CallUp AND NOT AtTop) THEN
                State := 0;
                MotorUp := FALSE;
                MotorDown := FALSE;
            END_IF;
    END_CASE;
END_IF;

// Safety checks
IF MotorUp AND MotorDown THEN
    MotorUp := FALSE;
    MotorDown := FALSE;
END_IF;

END_PROGRAM

