        END_IF;
END_CASE

// Safety conditions
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

IF NOT EStop THEN
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
    State := 0;
END_IF;

IF Level < LIQ_MIN THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

END_PROGRAM

PROGRAM batch_reactor
VAR
    State : INT;
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
    LIQ_MIN : CONST INT := 10;
    LVL_HIGH : CONST INT := 80;
    LVL_LOW : CONST INT := 5;
    TEMP_SET : CONST INT := 100;
    PT_REACT : CONST TIME := T#3s;
    T_Fill : TON;
    T_Heat : TON;
END_VAR

IF EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSE
    CASE State OF
        0: // Idle
            IF StartBatch AND Level >= LIQ_MIN THEN
                State := 1;
                T_Fill(IN := TRUE, PT := T#0s);
                T_Heat(IN := FALSE, PT := T#0s);
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            END_IF;

        1: // Fill
            IF T_Fill.Q OR Level >= LVL_HIGH THEN
                State := 2;
                T_Fill(IN := FALSE, PT := T#0s);
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            ELSE
                FillValve := TRUE;
            END_IF;

        2: // Heat
            IF T_Heat.Q OR Temp >= TEMP_SET THEN
                State := 3;
                T_Heat(IN := FALSE, PT := T#0s);
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            ELSE
                Heater := TRUE;
                Agitator := TRUE;
            END_IF;

        3: // React
            IF NOT T_Heat.Q THEN
                T_Heat(IN := TRUE, PT := PT_REACT);
            END_IF;
            IF T_Heat.Q THEN
                State := 4;
                T_Heat(IN := FALSE, PT := T#0s);
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            ELSE
                Heater := TRUE;
                Agitator := TRUE;
            END_IF;

        4: // Drain
            IF T_Fill.Q OR Level <= LVL_LOW THEN
                State := 0;
                T_Fill(IN := FALSE, PT := T#0s);
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            ELSE
                DrainValve := TRUE;
            END_IF;
    END_CASE;
END_IF;

// Safety checks
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

IF NOT (Level >= LIQ_MIN) AND (Heater OR Agitator) THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;
END_PROGRAM

