    1:
        MainK := TRUE;
        StarK := TRUE;
        DeltaK := FALSE;
        StarTimer(IN := TRUE, PT := PT_STAR);
        IF NOT StarTimer.Q OR StopPB OR NOT EStop THEN
            State := 0;
        ELSIF StarTimer.Q THEN
            State := 2;
