        IF EStop OR Level >= HighLevel THEN
            State := 2;
            Pump := FALSE;
            Valve := TRUE;
        END_IF;

    2: -- Draining
        IF EStop OR Level <= LowLevel THEN
            State := 0;
            Pump := FALSE;
            Valve := FALSE;
        END_IF;
END_CASE;

-- Safety checks
IF Pump AND Valve THEN
    Pump := FALSE;
    Valve := FALSE;
END_IF;

IF Level >= HighLevel THEN
    Pump := FALSE;
END_IF;

IF Level <= LowLevel THEN
    Valve := FALSE;
END_IF;

END_PROGRAM

