// Check for emergency stop
IF NOT EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
    PumpsRunning := FALSE;
    RETURN;
END_IF;

// Detect falling edge of Demand
IF Demand AND NOT PrevDemand THEN
    PumpsRunning := FALSE;
END_IF;

PrevDemand := Demand;

// Alternate lead pump if demand ends
IF NOT Demand AND PumpsRunning THEN
    Lead := 1 - Lead; // Toggle between 0 and 1
    PumpsRunning := FALSE;
END_IF;

// Assign pumps based on lead and demand
CASE Lead OF
    0:
        Pump1 := Demand;
        Pump2 := FALSE;
    1:
        Pump1 := FALSE;
        Pump2 := Demand;
    ELSE
        Pump1 := FALSE;
        Pump2 := FALSE;
END_CASE;

PumpsRunning := Pump1 OR Pump2;

