    OpenTimer(IN := FALSE);
END_IF;

IF CloseCmd AND NOT CloseLimit AND NOT Obstruction THEN
    CloseTimer(IN := TRUE, PT := T#0s);
ELSE
    CloseTimer(IN := FALSE);
END_IF;

