    Count := MIN(Count + 1, 3);
END_IF;

-- Reset count if Reset is high
IF Reset THEN
    Count := 0;
END_IF;

-- Assert Done when Count reaches 3
Done := (Count = 3);

END_PROGRAM

PROGRAM dosing
VAR_INPUT
    Trigger : BOOL;
    Reset : BOOL;
END_VAR

VAR_OUTPUT
    Done : BOOL;
END_VAR

VAR
    Count : INT := 0;
    PrevTrigger : BOOL := FALSE;
END_VAR

Done := FALSE;

IF Reset THEN
    Count := 0;
    Done := FALSE;
END_IF;

IF NOT PrevTrigger AND Trigger THEN
    Count := Count + 1;
    IF Count > 3 THEN
        Count := 3;
    END_IF;
END_IF;

PrevTrigger := Trigger;

IF Count >= 3 THEN
    Done := TRUE;
END_IF;
END_PROGRAM

